using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

public class SothisOmensHandler : ReferenceSingleton<SothisOmensHandler>
{
	[SerializeField]
	private HourglassModuleOmenData hourglassModuleOmenData;

	[NonSerialized]
	public bool BehenianHourglassActive;

	[NonSerialized]
	public List<Action<int>> OnPlayerOrSentinelCorruptAfflictionSingleTimeOmenActions = new List<Action<int>>();

	[NonSerialized]
	public List<Action<GameObject, int>> OnPlayerOrSentinelCorruptAfflictionMultipleTimesOmenActions = new List<Action<GameObject, int>>();

	[NonSerialized]
	public List<Action<int>> OnPlayerSentinelCorruptAfflictionEnemyMultipleTimesOmenActions = new List<Action<int>>();

	[NonSerialized]
	public Action TaintedKhepreshOmenAction;

	[NonSerialized]
	public Func<int, int> TaintedKhepreshReliefOmenAction;

	[NonSerialized]
	public Action GoddessCartoucheOmenAction;

	[NonSerialized]
	public Action<int> BoneKhopeshOmenAction;

	[NonSerialized]
	public Action EtherealPlumeOmenAction;

	[NonSerialized]
	public Action<int> SingingUrnOmenAction;

	[NonSerialized]
	public Action<int> SlateOfPlentyOmenAction;

	[NonSerialized]
	public Action HourglassModuleOmenAction;

	[NonSerialized]
	public Action FervorousSundialOmenAction;

	[NonSerialized]
	public Action<GameObject> FireIceCreamOmenAction;

	public bool IsBehenianHourglassActive()
	{
		return BehenianHourglassActive;
	}

	public void ActivateOnCorruptAfflictionSingleTimeOmens(int corruptAfflictionAmount)
	{
		for (int i = 0; i < OnPlayerOrSentinelCorruptAfflictionSingleTimeOmenActions.Count; i++)
		{
			OnPlayerOrSentinelCorruptAfflictionSingleTimeOmenActions[i](corruptAfflictionAmount);
		}
	}

	public void ActivateOnCorruptAfflictionMultipleTimesOmens(GameObject target, int corruptAfflictionAmount)
	{
		for (int i = 0; i < OnPlayerOrSentinelCorruptAfflictionMultipleTimesOmenActions.Count; i++)
		{
			OnPlayerOrSentinelCorruptAfflictionMultipleTimesOmenActions[i](target, corruptAfflictionAmount);
		}
	}

	public void ActivateOnCorruptAfflictionEnemyMultipleTimesOmens(int corruptAfflictionAmount)
	{
		for (int i = 0; i < OnPlayerSentinelCorruptAfflictionEnemyMultipleTimesOmenActions.Count; i++)
		{
			OnPlayerSentinelCorruptAfflictionEnemyMultipleTimesOmenActions[i](corruptAfflictionAmount);
		}
	}

	public bool ActivateTaintedKhepreshOmen(bool activateFeedback)
	{
		if (TaintedKhepreshOmenAction != null)
		{
			if (activateFeedback)
			{
				TaintedKhepreshOmenAction();
			}
			return true;
		}
		return false;
	}

	public void ActivateGoddessCartoucheOmen()
	{
		GoddessCartoucheOmenAction?.Invoke();
	}

	public void ActivateBoneKhopeshOmen(int soulHeatCounter)
	{
		BoneKhopeshOmenAction?.Invoke(soulHeatCounter);
	}

	public bool IsBoneKhopeshOmenActive()
	{
		return BoneKhopeshOmenAction != null;
	}

	public bool ActivateEtherealPlumeOmenActiveOmen()
	{
		if (EtherealPlumeOmenAction != null)
		{
			EtherealPlumeOmenAction();
			return true;
		}
		return false;
	}

	public bool IsEtherealPlumeOmenActiveAndAfflictionCorruption(CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		if (corruptionPurifyModifierEnum != CorruptionPurifyModifierEnum.AFFLICTIONRELIEF)
		{
			return false;
		}
		return EtherealPlumeOmenAction != null;
	}

	public void ActivateSingingUrnOmen(int sequenceAmount)
	{
		SingingUrnOmenAction?.Invoke(sequenceAmount);
	}

	public void ActivateSlateOfPlentyOmen(int exceedPurifyAmount)
	{
		SlateOfPlentyOmenAction?.Invoke(exceedPurifyAmount);
	}

	public bool IsHourglassModuleOmenActive()
	{
		return HourglassModuleOmenAction != null;
	}

	public void ActivateHourglassModuleAction()
	{
		HourglassModuleOmenAction?.Invoke();
	}

	public bool IsFervorousSundialOmenActiveActivateAction()
	{
		if (FervorousSundialOmenAction != null)
		{
			FervorousSundialOmenAction();
			return true;
		}
		return false;
	}

	public bool IsFervorousSundialOmenActive()
	{
		return FervorousSundialOmenAction != null;
	}
}
